filter="${1:-}"
fail=0
# Never cache bytecode of mutated sources. Python validates a .pyc by the
# source's whole-second mtime and size; a same-length mutant restored within
# the same second left the MUTATED bytecode in use by every later run
# (found 2026-10-07: "if named" -> "if False" broke the real suite).
export PYTHONDONTWRITEBYTECODE=1
purge_pyc() { rm -f "$(dirname "$1")/__pycache__/$(basename "$1" .py)".*.pyc; }
for entry in "${MUTANTS[@]}"; do
  IFS='|' read -r name file expr selector <<<"$entry"
  [[ -n "$filter" && "$name" != *"$filter"* ]] && continue
  cp "$file" "$file.mutbak"
  trap 'mv -f "$file.mutbak" "$file"; purge_pyc "$file"' EXIT INT TERM
  sed -i "$expr" "$file"
  purge_pyc "$file"
  if cmp -s "$file" "$file.mutbak"; then
    echo "STALE    $name  (sed matched nothing; update the mutant)"
    fail=1
  else
    # bash -c so quoted selectors (-k 'a or b') stay one argument; unquoted,
    # pytest got a broken -k expression and the error counted as a kill.
    bash -c "$PY -m pytest $selector -q -p no:warnings -x" >/dev/null 2>&1
    rc=$?
    # Exit 5 is "no tests collected": a selector typo would otherwise count
    # as a kill and the mutant would prove nothing.
    if [[ $rc -eq 5 ]]; then
      echo "NOTESTS  $name  (selector '$selector' matched no tests)"
      fail=1
    elif [[ $rc -eq 0 ]]; then
      echo "SURVIVED $name  (tests still pass with the bug in place)"
      fail=1
    else
      echo "killed   $name"
    fi
  fi
  mv -f "$file.mutbak" "$file"
  purge_pyc "$file"
  trap - EXIT INT TERM
done
exit $fail
